import re

def entities(doc, scope):
    scope_children = scope_nodes(doc, scope)
    objects_node = None
    for node in scope_children:
        if node.get("kind") == "list" and "Objects" in node["title"]:
            objects_node = node
            break
    result = []
    if objects_node and objects_node.get("lines"):
        for line in objects_node["lines"]:
            m = re.match(r'Object (\d+): (.+)', line)
            if m:
                result.append({"id": m.group(1), "description": m.group(2)})
    return result

def recorded_end(doc, scope):
    scope_children = scope_nodes(doc, scope)
    max_time = -1
    found = False
    for node in scope_children:
        if node.get("kind") == "table" and "Motion log" in node["title"]:
            for _, row in table_rows(node):
                f = int(row["frame"])
                if f > max_time:
                    max_time = f
                found = True
    for node in scope_children:
        if node.get("kind") == "list" and "Events" in node["title"]:
            for line in node.get("lines", []):
                m = re.match(r'Frame (\d+):', line)
                if m:
                    f = int(m.group(1))
                    if f > max_time:
                        max_time = f
                    found = True
    return float(max_time) if found else None

def _find_node(scope_children, title_part):
    for node in scope_children:
        if title_part in node["title"]:
            return node
    return None

def inputs(doc, scope):
    scope_children = scope_nodes(doc, scope)
    events_node = _find_node(scope_children, "Events")
    motion_node = _find_node(scope_children, "Motion log")
    objects_node = _find_node(scope_children, "Objects")

    obj_desc = {}
    if objects_node and objects_node.get("lines"):
        for line in objects_node["lines"]:
            m = re.match(r'Object (\d+): (.+)', line)
            if m:
                obj_desc[m.group(1)] = m.group(2)

    motion_lookup = {}
    if motion_node:
        for row_idx, row in table_rows(motion_node):
            frame = row["frame"]
            obj_id = row["object"].split(" ", 1)[0]
            motion_lookup[(frame, obj_id)] = (row_idx, row)

    result = []
    if not events_node or not events_node.get("lines"):
        return result

    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r'Frame (\d+): Object (\d+) \(.+\) is in view when the video begins\.', line)
        if m:
            frame_str = m.group(1)
            obj_id = m.group(2)
            fields = {"description": obj_desc.get(obj_id, "")}
            src = [[events_node["node_id"], line_idx]]
            if motion_lookup:
                key = (frame_str, obj_id)
                if key in motion_lookup:
                    r_idx, row = motion_lookup[key]
                    fields["x"] = float(row["x"])
                    fields["y"] = float(row["y"])
                    fields["vx"] = float(row["vx"])
                    fields["vy"] = float(row["vy"])
                    fields["speed"] = float(row["speed"])
                    src.append([motion_node["node_id"], r_idx,
                               ["frame", "object", "x", "y", "vx", "vy", "speed"]])
            result.append({
                "id": f"enter_{obj_id}",
                "time": float(frame_str),
                "kind": "object_enter",
                "entities": [obj_id],
                "fields": fields,
                "src": src
            })
    return result

def outcomes(doc, scope):
    scope_children = scope_nodes(doc, scope)
    events_node = _find_node(scope_children, "Events")
    result = []
    if not events_node or not events_node.get("lines"):
        return result
    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r'Frame (\d+): Object (\d+) \(.+\) and Object (\d+) \(.+\) collide\.', line)
        if m:
            result.append({
                "time": float(m.group(1)),
                "kind": "collision",
                "entities": [m.group(2), m.group(3)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
            continue
        m = re.match(r'Frame (\d+): Object (\d+) \(.+\) exits the scene\.', line)
        if m:
            result.append({
                "time": float(m.group(1)),
                "kind": "exit",
                "entities": [m.group(2)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
    return result

def params(doc, scope):
    return {"stationary_speed_threshold": 0.1}


