import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)

    if rec_end is None:
        start = start if start is not None else 0.0
        horizon = horizon if horizon is not None else start + 128.0
    else:
        start = start if start is not None else 0.0
        horizon = horizon if horizon is not None else rec_end

    threshold = params.get("stationary_speed_threshold", 0.1)

    DT = 5.0 / 128.0  # seconds per frame
    FRICTION = 0.003  # per frame
    COLLISION_DIST = 0.5  # 2 * radius
    EXIT_BOUNDARY = 5.0

    objects = {}
    entries = {}
    for inp in inputs:
        if inp["kind"] == "object_enter":
            obj_id = inp["entities"][0]
            desc = inp["fields"].get("description", "")
            material = "metal" if "metal" in desc else "rubber"
            objects[obj_id] = {"material": material}
            entries[obj_id] = {
                "time": inp["time"],
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"]
            }

    def get_mass(oid):
        return 2.0 if objects[oid]["material"] == "metal" else 1.0

    def get_restitution(o1, o2):
        m1, m2 = objects[o1]["material"], objects[o2]["material"]
        if m1 == "metal" and m2 == "metal":
            return 1.0
        elif m1 == "rubber" and m2 == "rubber":
            return 0.25
        else:
            return 0.5

    # Initialize state at start
    state = {}
