import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    threshold = params.get("stationary_speed_threshold", 0.1)

    # Parse inputs - MUST use inputs for initial conditions
    objects = {}
    entry_info = {}
    for inp in inputs:
        if inp["kind"] == "object_enter":
            obj_id = inp["entities"][0]
            desc = inp["fields"].get("description", "")
            material = "metal" if "metal" in desc else "rubber"
            objects[obj_id] = material
            entry_info[obj_id] = {
                "enter_time": inp["time"],
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"]
            }

    if not objects:
        return []

    # Read document for objects that enter later (not in inputs)
    scope_children = scope_nodes(doc, scope)
    late_entries = {}
    for node in scope_children:
        if "Events" in node.get("title", ""):
            for line in node.get("lines", []):
                m = re.match(r'Frame (\d+): Object (\d+) \((\w+) (\w+) (\w+)\) enters the scene\.', line)
                if m:
                    frame = int(m.group(1))
                    obj_id = m.group(2)
                    material = m.group(4)
                    if obj_id not in objects:
                        objects[obj_id] = material
                        late_entries[obj_id] = {
                            "enter_time": float(frame),
                            "material": material
                        }
            break

    # Read motion log for late entries' initial positions
    for node in scope_children:
        if "Motion log" in node.get("title", ""):
            for _, row in table_rows(node):
                frame = int(row["frame"])
                obj_id = row["object"].split()[0]
                if obj_id in late_entries:
                    le = late_entries[obj_id]
                    if frame == int(le["enter_time"]):
                        entry_info[obj_id] = {
                            "enter_time": le["enter_time"],
                            "x": float(row["x"]),
                            "y": float(row["y"]),
                            "vx": float(row["vx"]),
                            "vy": float(row["vy"])
                        }
            break

    DT = 5.0 / 128.0
    FRICTION = 0.0035
    EXIT_BOUNDARY = 5.0
    COLLISION_DIST = 0.65

    def get_mass(oid):
        return 2.0 if objects.get(oid) == "metal" else 1.0

    def get_restitution(o1, o2):
        m1 = objects.get(o1, "rubber")
        m2 = objects.get(o2, "rubber")
        if m1 == "metal" and m2 == "metal":
            return 1.0
        elif m1 == "rubber" and m2 == "rubber":
            return 0.25
        return 0.5

    # Initialize state from inputs
    state = {}
    for obj_id, info in entry_info.items():
        state[obj_id] = {
            "x": info["x"],
            "y": info["y"],
            "vx": info["vx"],
            "vy": info["vy"],
            "active": info["enter_time"] <= 0.0
        }

    # Determine frame range
    if rec_end is None:
        t_end = int(start) + 128 if horizon is None else int(horizon)
    else:
        t_end = int(rec_end) if horizon is None else int(horizon)

    outcomes = []
    exited = set()
    collision_set = set()

    for t in range(0, t_end + 1):
        # Activate objects entering at this frame
        for obj_id, info in entry_info.items():
            if abs(info["enter_time"] - t) < 1.0 and not state[obj_id]["active"]:
                dt = max(0.0, t - info["enter_time"])
                k = (1.0 - FRICTION) ** dt
                state[obj_id]["x"] = info["x"] + info["vx"] * DT * dt
                state[obj_id]["y"] = info["y"] + info["vy"] * DT * dt
                state[obj_id]["vx"] = info["vx"] * k
                state[obj_id]["vy"] = info["vy"] * k
                state[obj_id]["active"] = True

        active = [oid for oid in state if state[oid]["active"] and oid not in exited]

        # Sub-frame collision detection
        remaining = 1.0
        sub_iters = 0
        while remaining > 0.02 and sub_iters < 12:
            min_frac = None
            min_pair = None
            for i in range(len(active)):
                for j in range(i+1, len(active)):
                    o1, o2 = active[i], active[j]
                    s1, s2 = state[o1], state[o2]
                    dx = s2["x"] - s1["x"]
                    dy = s2["y"] - s1["y"]
                    dvx = (s2["vx"] - s1["vx"]) * DT
                    dvy = (s2["vy"] - s1["vy"]) * DT

                    a = dvx*dvx + dvy*dvy
                    if a < 1e-20:
                        continue
                    b = 2.0*(dx*dvx + dy*dvy)
                    c = dx*dx + dy*dy - COLLISION_DIST*COLLISION_DIST
                    disc = b*b - 4.0*a*c
                    if disc < 0:
                        continue

                    sqrt_d = math.sqrt(disc)
                    candidates = sorted([(-b - sqrt_d)/(2.0*a), (-b + sqrt_d)/(2.0*a)])
                    for tt in candidates:
                        if 1e-10 < tt < remaining:
                            nxx = dx + dvx*tt
                            nyy = dy + dvy*tt
                            dd = math.sqrt(nxx*nxx + nyy*nyy)
                            if dd > 1e-10:
                                dvn = ((s1["vx"]-s2["vx"])*nxx/dd + (s1["vy"]-s2["vy"])*nyy/dd)
                                if dvn > 1e-10 and (min_frac is None or tt < min_frac):
                                    min_frac = tt
                                    min_pair = (o1, o2)

            if min_frac is None:
                break

            # Advance to collision
            for oid in active:
                state[oid]["x"] += state[oid]["vx"] * DT * min_frac
                state[oid]["y"] += state[oid]["vy"] * DT * min_frac

            # Resolve collision
            o1, o2 = min_pair
            s1, s2 = state[o1], state[o2]
            dx = s2["x"] - s1["x"]
            dy = s2["y"] - s1["y"]
            dist = math.sqrt(dx*dx + dy*dy)
            if dist > 1e-10:
                nx, ny = dx/dist, dy/dist
                dvn = (s1["vx"]-s2["vx"])*nx + (s1["vy"]-s2["vy"])*ny
                if dvn > 1e-10:
                    m1, m2 = get_mass(o1), get_mass(o2)
                    e = get_restitution(o1, o2)
                    imp = (1.0 + e) * dvn / (1.0/m1 + 1.0/m2)
                    s1["vx"] -= imp/m1*nx
                    s1["vy"] -= imp/m1*ny
                    s2["vx"] += imp/m2*nx
                    s2["vy"] += imp/m2*ny
                    if dist < COLLISION_DIST:
                        ov = (COLLISION_DIST - dist) * 0.5
                        s1["x"] -= nx*ov
                        s1["y"] -= ny*ov
                        s2["x"] += nx*ov
                        s2["y"] += ny*ov

            key = tuple(sorted([o1, o2]))
            if key not in collision_set:
                collision_set.add(key)
                outcomes.append({
                    "time": float(t),
                    "kind": "collision",
                    "entities": sorted([o1, o2]),
                    "value": None,
                    "src": []
                })

            remaining -= min_frac
            sub_iters += 1

        # Advance remaining time
        for oid in active:
            s = state[oid]
            s["x"] += s["vx"] * DT * remaining
            s["y"] += s["vy"] * DT * remaining
            s["vx"] *= (1.0 - FRICTION)
            s["vy"] *= (1.0 - FRICTION)
            spd = math.sqrt(s["vx"]**2 + s["vy"]**2)
            if spd < threshold:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check exits
        for oid in list(active):
            s = state[oid]
            if abs(s["x"]) > EXIT_BOUNDARY or abs(s["y"]) > EXIT_BOUNDARY:
                outcomes.append({
                    "time": float(t),
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })
                exited.add(oid)

    # Only return outcomes after start
    actual_start = start if start is not None else 0.0
    return [o for o in outcomes if o["time"] > actual_start]

