import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_speed_threshold", 0.1)

    # Parse inputs
    objects = {}
    for inp in inputs:
        if inp["kind"] == "object_enter":
            obj_id = inp["entities"][0]
            desc = inp["fields"].get("description", "")
            material = "metal" if "metal" in desc else "rubber"
            objects[obj_id] = {
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"],
                "material": material,
                "enter_time": inp["time"],
                "active": False
            }

    if not objects:
        return []

    # Determine time range
    if horizon is None:
        he = recorded_end(doc, scope)
        horizon = float(he) if he is not None else 127.0

    if start is None:
        start = 0.0

    # Simulation parameters (estimated from data)
    DT = 0.027
    FRICTION = {"metal": 0.992, "rubber": 0.989}
    COLLISION_THRESHOLD = 0.45
    MASS = {"metal": 2.0, "rubber": 1.0}
    RESTITUTION = {
        ("metal", "metal"): 0.7,
        ("metal", "rubber"): 0.4,
        ("rubber", "metal"): 0.4,
        ("rubber", "rubber"): 0.2
    }
    EXIT_X = 4.5
    EXIT_Y = 3.0

    min_enter = min(obj["enter_time"] for obj in objects.values())
    sim_start = int(min_enter)
    start_frame = max(int(start), sim_start)
    end_frame = int(horizon)

    if start_frame > end_frame:
        return []

    # Pre-simulation: advance state to start_frame
    pre_collision_tracker = set()
    for frame in range(sim_start, start_frame):
        _step(objects, frame, FRICTION, DT, COLLISION_THRESHOLD, MASS, RESTITUTION,
              EXIT_X, EXIT_Y, [], pre_collision_tracker, set())

    # Main simulation: record outcomes
    outcomes = []
    collision_tracker = set()
    exit_tracker = set()
    for frame in range(start_frame, end_frame + 1):
        _step(objects, frame, FRICTION, DT, COLLISION_THRESHOLD, MASS, RESTITUTION,
              EXIT_X, EXIT_Y, outcomes, collision_tracker, exit_tracker)

    return [o for o in outcomes if o["time"] > start]


def _step(objects, frame, friction, dt, collision_threshold, mass, restitution,
          exit_x, exit_y, outcomes, collision_tracker, exit_tracker):
    # Activate objects entering at or before this frame
    for obj in objects.values():
        if not obj["active"] and obj["enter_time"] <= frame:
            obj["active"] = True

    # Check collisions at current positions
    active_ids = [oid for oid, obj in objects.items() if obj["active"]]
    for i in range(len(active_ids)):
        for j in range(i + 1, len(active_ids)):
            oid1, oid2 = active_ids[i], active_ids[j]
            obj1, obj2 = objects[oid1], objects[oid2]
            dx = obj2["x"] - obj1["x"]
            dy = obj2["y"] - obj1["y"]
            dist = math.sqrt(dx * dx + dy * dy)
            if dist < collision_threshold:
                _handle_collision(obj1, obj2, mass, restitution)
                key = tuple(sorted([oid1, oid2], key=int))
                if key not in collision_tracker:
                    collision_tracker.add(key)
                    outcomes.append({
                        "time": float(frame),
                        "kind": "collision",
                        "entities": sorted([oid1, oid2], key=int),
                        "value": None,
                        "src": []
                    })

    # Check for exits
    for obj_id, obj in objects.items():
        if obj_id in exit_tracker:
            continue
        if not obj["active"]:
            continue
        if abs(obj["x"]) > exit_x or abs(obj["y"]) > exit_y:
            exit_tracker.add(obj_id)
            outcomes.append({
                "time": float(frame),
                "kind": "exit",
                "entities": [obj_id],
                "value": None,
                "src": []
            })

    # Update positions and velocities to next frame
    for obj in objects.values():
        if not obj["active"]:
            continue
        obj["x"] += obj["vx"] * dt
        obj["y"] += obj["vy"] * dt
        f = friction[obj["material"]]
        obj["vx"] *= f
        obj["vy"] *= f


def _handle_collision(obj1, obj2, mass, restitution):
    dx = obj2["x"] - obj1["x"]
    dy = obj2["y"] - obj1["y"]
    dist = math.sqrt(dx * dx + dy * dy)
    if dist < 0.001:
        return
    nx, ny = dx / dist, dy / dist
    dvx = obj1["vx"] - obj2["vx"]
    dvy = obj1["vy"] - obj2["vy"]
    dvn = dvx * nx + dvy * ny
    if dvn <= 0:
        return
    e = restitution.get((obj1["material"], obj2["material"]), 0.4)
    m1 = mass[obj1["material"]]
    m2 = mass[obj2["material"]]
    j = -(1 + e) * dvn / (1.0 / m1 + 1.0 / m2)
    obj1["vx"] += j / m1 * nx
    obj1["vy"] += j / m1 * ny
    obj2["vx"] -= j / m2 * nx
    obj2["vy"] -= j / m2 * ny

