def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_speed_threshold", 0.1)

    # Parse inputs to initialize objects
    objects = {}
    for inp in inputs:
        if inp["kind"] == "object_enter":
            obj_id = inp["entities"][0]
            desc = inp["fields"].get("description", "")
            material = "metal" if "metal" in desc else "rubber"
            objects[obj_id] = {
                "x": float(inp["fields"].get("x", 0)),
                "y": float(inp["fields"].get("y", 0)),
                "vx": float(inp["fields"].get("vx", 0)),
                "vy": float(inp["fields"].get("vy", 0)),
                "material": material,
                "enter_time": inp["time"],
                "active": False,
                "exited": False
            }

    if not objects:
        return []

    if horizon is None:
        he = recorded_end(doc, scope)
        horizon = float(he) if he is not None else 127.0
    if start is None:
        start = 0.0

    end_frame = int(horizon)
    start_frame = int(start)

    # Physics parameters calibrated from Video 14878 data
    # dt calculated from y change of obj 0: frame 0 to 7, y: -2.06 to -1.53
    # avg vy ≈ 2.72, dy=0.53, dt = 0.53/(7*2.72) ≈ 0.0278
    DT = 0.0278
    # Friction from vy decay: 2.79 * f^7 = 2.65, f = 0.9922
    FRICTION = {"metal": 0.9922, "rubber": 0.985}
    # Exit boundary: objects visible up to ~4.0-4.5 based on observed positions
    # Use slightly less to allow exits to be detected
    EXIT_X = 4.2
    EXIT_Y = 3.5
    COLLISION_DIST = 0.5
    MASS = {"metal": 2.0, "rubber": 1.0}
    RESTITUTION = 0.5

    min_enter = min(int(obj["enter_time"]) for obj in objects.values())

    outcomes = []
    collision_set = set()
    exit_set = set()

    for frame in range(min_enter, end_frame + 1):
        # Activate objects entering at or before this frame
        for obj_id, obj in objects.items():
            if not obj["active"] and not obj["exited"] and frame >= obj["enter_time"]:
                obj["active"] = True

        active_ids = [oid for oid, obj in objects.items() if obj["active"] and not obj["exited"]]

        # Update positions
        for obj in objects.values():
            if obj["active"] and not obj["exited"]:
                obj["x"] += obj["vx"] * DT
                obj["y"] += obj["vy"] * DT

        # Check collisions
        for i in range(len(active_ids)):
            for j in range(i + 1, len(active_ids)):
                a, b = active_ids[i], active_ids[j]
                obj_a, obj_b = objects[a], objects[b]
                dx = obj_b["x"] - obj_a["x"]
                dy = obj_b["y"] - obj_a["y"]
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < COLLISION_DIST and dist > 0.001:
                    nx, ny = dx / dist, dy / dist
                    dvx = obj_a["vx"] - obj_b["vx"]
                    dvy = obj_a["vy"] - obj_b["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        ma = MASS[obj_a["material"]]
                        mb = MASS[obj_b["material"]]
                        impulse = -(1 + RESTITUTION) * dvn / (1.0 / ma + 1.0 / mb)
                        obj_a["vx"] += impulse * nx / ma
                        obj_a["vy"] += impulse * ny / ma
                        obj_b["vx"] -= impulse * nx / mb
                        obj_b["vy"] -= impulse * ny / mb

                        key = tuple(sorted([a, b], key=lambda x: int(x)))
                        if key not in collision_set:
                            collision_set.add(key)
                            if frame >= start_frame:
                                outcomes.append({
                                    "time": float(frame),
                                    "kind": "collision",
                                    "entities": sorted([a, b], key=lambda x: int(x)),
                                    "value": None,
                                    "src": []
                                })

        # Check exits
        for obj_id in active_ids:
            if obj_id not in exit_set:
                obj = objects[obj_id]
                if abs(obj["x"]) > EXIT_X or abs(obj["y"]) > EXIT_Y:
                    obj["exited"] = True
                    exit_set.add(obj_id)
                    if frame >= start_frame:
                        outcomes.append({
                            "time": float(frame),
                            "kind": "exit",
                            "entities": [obj_id],
                            "value": None,
                            "src": []
                        })

        # Apply friction
        for obj in objects.values():
            if obj["active"] and not obj["exited"]:
                f = FRICTION[obj["material"]]
                obj["vx"] *= f
                obj["vy"] *= f

    return outcomes

