                    dvx = obj_a["vx"] - obj_b["vx"]
                    dvy = obj_a["vy"] - obj_b["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        ma = mass[obj_a["material"]]
                        mb = mass[obj_b["material"]]
                        impulse = -(1 + RESTITUTION) * dvn / (1.0 / ma + 1.0 / mb)
                        obj_a["vx"] += impulse * nx / ma
                        obj_a["vy"] += impulse * ny / ma
                        obj_b["vx"] -= impulse * nx / mb
                        obj_b["vy"] -= impulse * ny / mb

                        key = tuple(sorted([a, b], key=lambda x: int(x)))
                        if key not in collision_set:
                            collision_set.add(key)
                            outcomes.append({
                                "time": float(frame),
                                "kind": "collision",
                                "entities": sorted([a, b], key=lambda x: int(x)),
                                "value": None,
                                "src": []
                            })

        # Check exits after position update
        active_ids = [oid for oid, obj in objects.items() if obj["active"] and not obj["exited"]]
        for obj_id in active_ids:
            if obj_id not in exit_set:
                obj = objects[obj_id]
                if abs(obj["x"]) > EXIT_X or abs(obj["y"]) > EXIT_Y:
                    obj["exited"] = True
                    exit_set.add(obj_id)
                    outcomes.append({
                        "time": float(frame),
                        "kind": "exit",
                        "entities": [obj_id],
                        "value": None,
                        "src": []
                    })

        # Apply friction to velocities
        for obj_id, obj in objects.items():
            if obj["active"] and not obj["exited"]:
                f = FRICTION_COEF[obj["material"]]
                obj["vx"] *= f
                obj["vy"] *= f

    return outcomes


def _simulation_step(objects, frame, dt, friction, collision_dist, mass, restitution,
                     exit_x, exit_y, outcomes, collision_set, exit_set, record):
    # Update positions
    for obj_id, obj in objects.items():
        if obj["active"] and not obj["exited"]:
            obj["x"] += obj["vx"] * dt
            obj["y"] += obj["vy"] * dt

    # Check collisions
    active_ids = [oid for oid, obj in objects.items() if obj["active"] and not obj["exited"]]
    for i in range(len(active_ids)):
        for j in range(i + 1, len(active_ids)):
            a, b = active_ids[i], active_ids[j]
            obj_a, obj_b = objects[a], objects[b]

            dx = obj_b["x"] - obj_a["x"]
            dy = obj_b["y"] - obj_a["y"]
            dist = math.sqrt(dx * dx + dy * dy)

            if dist < collision_dist and dist > 0.001:
                nx, ny = dx / dist, dy / dist
                dvx = obj_a["vx"] - obj_b["vx"]
                dvy = obj_a["vy"] - obj_b["vy"]
                dvn = dvx * nx + dvy * ny

                if dvn > 0:
                    ma = mass[obj_a["material"]]
                    mb = mass[obj_b["material"]]
                    impulse = -(1 + restitution) * dvn / (1.0 / ma + 1.0 / mb)
                    obj_a["vx"] += impulse * nx / ma
                    obj_a["vy"] += impulse * ny / ma
                    obj_b["vx"] -= impulse * nx / mb
                    obj_b["vy"] -= impulse * ny / mb

                    if record:
                        key = tuple(sorted([a, b], key=lambda x: int(x)))
                        if key not in collision_set:
                            collision_set.add(key)
                            outcomes.append({
                                "time": float(frame),
                                "kind": "collision",
                                "entities": sorted([a, b], key=lambda x: int(x)),
                                "value": None,
                                "src": []
                            })

    # Check exits
    active_ids = [oid for oid, obj in objects.items() if obj["active"] and not obj["exited"]]
    for obj_id in active_ids:
        if obj_id not in exit_set:
            obj = objects[obj_id]
            if abs(obj["x"]) > exit_x or abs(obj["y"]) > exit_y:
                obj["exited"] = True
                exit_set.add(obj_id)
                if record:
                    outcomes.append({
                        "time": float(frame),
                        "kind": "exit",
                        "entities": [obj_id],
                        "value": None,
                        "src": []
                    })

    # Apply friction to velocities
    for obj_id, obj in objects.items():
        if obj["active"] and not obj["exited"]:
            f = friction[obj["material"]]
            obj["vx"] *= f
            obj["vy"] *= f

