import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        try:
            h = recorded_end(doc, scope)
            horizon = h if h is not None else 127.0
        except:
            horizon = 127.0
    if start is None:
        start = 0.0

    collision_threshold = 0.45
    exit_bound = 3.2

    objs = {}
    for inp in inputs:
        if inp["kind"] == "object_enter":
            oid = inp["entities"][0]
            objs[oid] = {
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"],
                "active": False,
                "enter_time": inp["time"]
            }

    outcomes = []
    t = 0.0
    max_t = int(math.ceil(horizon))

    while t <= max_t:
        # Activate objects that enter at or before current time
        for o in objs.values():
            if not o["active"] and o["enter_time"] <= t:
                o["active"] = True

        # Update positions
        for o in objs.values():
            if o["active"]:
                o["x"] += o["vx"]
                o["y"] += o["vy"]

        # Check collisions
        oids = list(objs.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                o1, o2 = objs[oids[i]], objs[oids[j]]
                if not o1["active"] or not o2["active"]:
                    continue
                dx = o2["x"] - o1["x"]
                dy = o2["y"] - o1["y"]
                dist = math.hypot(dx, dy)
                if dist < collision_threshold and dist > 1e-6:
                    outcomes.append({
                        "kind": "collision",
                        "time": t,
                        "entities": [oids[i], oids[j]],
                        "value": None
                    })
                    # Resolve elastic collision (equal mass assumption)
                    nx, ny = dx/dist, dy/dist
                    dvx = o1["vx"] - o2["vx"]
                    dvy = o1["vy"] - o2["vy"]
                    dvn = dvx*nx + dvy*ny
                    if dvn > 0:
                        o1["vx"] -= dvn * nx
                        o1["vy"] -= dvn * ny
                        o2["vx"] += dvn * nx
                        o2["vy"] += dvn * ny
                    # Separate slightly to prevent stickiness
                    overlap = collision_threshold - dist
                    shift = overlap/2 + 1e-6
                    o1["x"] -= shift * nx
                    o1["y"] -= shift * ny
                    o2["x"] += shift * nx
                    o2["y"] += shift * ny

        # Check exits
        for oid, o in objs.items():
            if o["active"] and (abs(o["x"]) > exit_bound or abs(o["y"]) > exit_bound):
                outcomes.append({
                    "kind": "exit",
                    "time": t,
                    "entities": [oid],
                    "value": None
                })
                o["active"] = False

        t += 1.0

    return [o for o in outcomes if o["time"] > start]

