                                break
                    obj_entries[oid] = {
                        "time": float(frame),
                        "x": x, "y": y, "vx": vx, "vy": vy
                    }

    # Build motion log lookup: obj_id -> sorted list of records
    motion_by_obj = {}
    if motion_node:
        for _, row in table_rows(motion_node):
            try:
                f = int(row["frame"])
            except (ValueError, TypeError):
                continue
            oid = row["object"].split()[0]
            try:
                rx, ry = float(row["x"]), float(row["y"])
                rvx, rvy = float(row["vx"]), float(row["vy"])
            except (ValueError, TypeError):
                continue
            if oid not in motion_by_obj:
                motion_by_obj[oid] = []
            motion_by_obj[oid].append({"frame": f, "x": rx, "y": ry, "vx": rvx, "vy": rvy})
        for oid in motion_by_obj:
            motion_by_obj[oid].sort(key=lambda r: r["frame"])

    # Initialize state at `start`
    state = {}
    for oid, entry in obj_entries.items():
        t_enter = entry["time"]
        if t_enter > start:
            continue

        # Try to get state from motion log at or just before start
        if oid in motion_by_obj and motion_by_obj[oid]:
            best = None
            for rec in motion_by_obj[oid]:
                if rec["frame"] <= start:
                    if best is None or rec["frame"] > best["frame"]:
                        best = rec
            if best is not None:
                dt = start - best["frame"]
                state[oid] = {
                    "x": best["x"] + best["vx"] * dt,
                    "y": best["y"] + best["vy"] * dt,
                    "vx": best["vx"],
                    "vy": best["vy"],
                    "active": True
                }
            else:
                dt = start - t_enter
                state[oid] = {
                    "x": entry["x"] + entry["vx"] * dt,
                    "y": entry["y"] + entry["vy"] * dt,
                    "vx": entry["vx"],
                    "vy": entry["vy"],
                    "active": True
                }
        else:
            dt = start - t_enter
            state[oid] = {
                "x": entry["x"] + entry["vx"] * dt,
                "y": entry["y"] + entry["vy"] * dt,
                "vx": entry["vx"],
                "vy": entry["vy"],
                "active": True
            }

    # Simulate frame by frame from start to horizon
    outcomes = []
    oids_sorted = sorted(state.keys(), key=lambda x: int(x))
    first_iter = True

    frame = int(math.ceil(start))
    while frame <= int(horizon):
        # Move objects to this frame
        if first_iter:
            dt = frame - start
            for o in state.values():
                if o["active"]:
                    o["x"] += o["vx"] * dt
                    o["y"] += o["vy"] * dt
            first_iter = False
        else:
            for o in state.values():
                if o["active"]:
                    o["x"] += o["vx"]
                    o["y"] += o["vy"]

        # Check exits at this frame
        for oid in oids_sorted:
            o = state[oid]
            if o["active"]:
                if abs(o["x"]) > exit_bound or abs(o["y"]) > exit_bound:
                    outcomes.append({
                        "kind": "exit",
                        "time": float(frame),
                        "entities": [oid],
                        "value": None
                    })
                    o["active"] = False

        # Check collisions at this frame
        for i in range(len(oids_sorted)):
            for j in range(i + 1, len(oids_sorted)):
                oi, oj = oids_sorted[i], oids_sorted[j]
                if not state[oi]["active"] or not state[oj]["active"]:
                    continue
                o1, o2 = state[oi], state[oj]
                dx = o2["x"] - o1["x"]
                dy = o2["y"] - o1["y"]
                dist = math.hypot(dx, dy)
                if dist < collision_threshold and dist > 1e-6:
                    nx = dx / dist
                    ny = dy / dist
                    dvx = o1["vx"] - o2["vx"]
                    dvy = o1["vy"] - o2["vy"]
                    dvn = dvx * nx + dvy * ny
                    if dvn > 0:
                        outcomes.append({
                            "kind": "collision",
                            "time": float(frame),
                            "entities": [oi, oj],
                            "value": None
                        })
                        # Elastic collision (equal mass)
                        o1["vx"] -= dvn * nx
                        o1["vy"] -= dvn * ny
                        o2["vx"] += dvn * nx
                        o2["vy"] += dvn * ny
                        # Separate objects to prevent repeated detection
                        shift = (collision_threshold - dist) / 2.0 + 1e-4
                        o1["x"] -= shift * nx
                        o1["y"] -= shift * ny
                        o2["x"] += shift * nx
                        o2["y"] += shift * ny

        frame += 1

    return outcomes

import re

def entities(doc, scope):
    scope_children = scope_nodes(doc, scope)
    objects_node = None
    for node in scope_children:
        if node.get("kind") == "list" and "Objects" in node["title"]:
            objects_node = node
            break
    result = []
    if objects_node and objects_node.get("lines"):
        for line in objects_node["lines"]:
            m = re.match(r'Object (\d+): (.+)', line)
            if m:
                result.append({"id": m.group(1), "description": m.group(2)})
    return result

def recorded_end(doc, scope):
    scope_children = scope_nodes(doc, scope)
    max_time = -1
    found = False
    for node in scope_children:
        if node.get("kind") == "table" and "Motion log" in node["title"]:
            for _, row in table_rows(node):
                f = int(row["frame"])
                if f > max_time:
                    max_time = f
                found = True
    for node in scope_children:
        if node.get("kind") == "list" and "Events" in node["title"]:
            for line in node.get("lines", []):
                m = re.match(r'Frame (\d+):', line)
                if m:
                    f = int(m.group(1))
                    if f > max_time:
                        max_time = f
                    found = True
    return float(max_time) if found else None

def _find_node(scope_children, title_part):
    for node in scope_children:
        if title_part in node["title"]:
            return node
    return None

def inputs(doc, scope):
    scope_children = scope_nodes(doc, scope)
    events_node = _find_node(scope_children, "Events")
    motion_node = _find_node(scope_children, "Motion log")
    objects_node = _find_node(scope_children, "Objects")

    obj_desc = {}
    if objects_node and objects_node.get("lines"):
        for line in objects_node["lines"]:
            m = re.match(r'Object (\d+): (.+)', line)
            if m:
                obj_desc[m.group(1)] = m.group(2)

    motion_lookup = {}
    if motion_node:
        for row_idx, row in table_rows(motion_node):
            frame = row["frame"]
            obj_id = row["object"].split(" ", 1)[0]
            motion_lookup[(frame, obj_id)] = (row_idx, row)

    result = []
    if not events_node or not events_node.get("lines"):
        return result

    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r'Frame (\d+): Object (\d+) \(.+\) is in view when the video begins\.', line)
        if m:
            frame_str = m.group(1)
            obj_id = m.group(2)
            fields = {"description": obj_desc.get(obj_id, "")}
            src = [[events_node["node_id"], line_idx]]
            if motion_lookup:
                key = (frame_str, obj_id)
                if key in motion_lookup:
                    r_idx, row = motion_lookup[key]
                    fields["x"] = float(row["x"])
                    fields["y"] = float(row["y"])
                    fields["vx"] = float(row["vx"])
                    fields["vy"] = float(row["vy"])
                    fields["speed"] = float(row["speed"])
                    src.append([motion_node["node_id"], r_idx,
                               ["frame", "object", "x", "y", "vx", "vy", "speed"]])
            result.append({
                "id": f"enter_{obj_id}",
                "time": float(frame_str),
                "kind": "object_enter",
                "entities": [obj_id],
                "fields": fields,
                "src": src
            })
    return result

def outcomes(doc, scope):
    scope_children = scope_nodes(doc, scope)
    events_node = _find_node(scope_children, "Events")
    result = []
    if not events_node or not events_node.get("lines"):
        return result
    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r'Frame (\d+): Object (\d+) \(.+\) and Object (\d+) \(.+\) collide\.', line)
        if m:
            result.append({
                "time": float(m.group(1)),
                "kind": "collision",
                "entities": [m.group(2), m.group(3)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
            continue
        m = re.match(r'Frame (\d+): Object (\d+) \(.+\) exits the scene\.', line)
        if m:
            result.append({
                "time": float(m.group(1)),
                "kind": "exit",
                "entities": [m.group(2)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
    return result

def params(doc, scope):
    return {"stationary_speed_threshold": 0.1}


