import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = 127.0

    collision_threshold = 0.35
    exit_bound = 5.0

    scope_children = scope_nodes(doc, scope)
    events_node = None
    motion_node = None
    for n in scope_children:
        if n.get("kind") == "list" and "Events" in n["title"]:
            events_node = n
        if n.get("kind") == "table" and "Motion log" in n["title"]:
            motion_node = n

    obj_entries = {}
    for inp in inputs:
        if inp["kind"] == "object_enter":
            oid = inp["entities"][0]
            obj_entries[oid] = {
                "time": inp["time"],
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"]
            }

    if events_node:
        for line in events_node.get("lines", []):
            m = re.match(r'Frame (\d+): Object (\d+) \(.+\) enters the scene\.', line)
            if m:
                frame = int(m.group(1))
                oid = m.group(2)
                if oid not in obj_entries:
                    x, y, vx, vy = 0.0, 0.0, 0.0, 0.0
                    if motion_node:
                        for _, row in table_rows(motion_node):
                            try:
                                rf = int(row["frame"])
                            except (ValueError, TypeError):
                                continue
                            obj = row["object"].split()[0]
                            if rf == frame and obj == oid:
                                try:
                                    x = float(row["x"])
                                    y = float(row["y"])
                                    vx = float(row["vx"])
                                    vy = float(row["vy"])
                                except (ValueError, TypeError):
                                    pass
                                break
                    obj_entries[oid] = {
                        "time": float(frame),
                        "x": x, "y": y, "vx": vx, "vy": vy
                    }

    motion_by_obj = {}
    if motion_node:
        for _, row in table_rows(motion_node):
            try:
                f = int(row["frame"])
            except (ValueError, TypeError):
                continue
            oid = row["object"].split()[0]
            try:
                rx, ry = float(row["x"]), float(row["y"])
                rvx, rvy = float(row["vx"]), float(row["vy"])
            except (ValueError, TypeError):
                continue
            if oid not in motion_by_obj:
                motion_by_obj[oid] = []
            motion_by_obj[oid].append({"frame": f, "x": rx, "y": ry, "vx": rvx, "vy": rvy})
        for oid in motion_by_obj:
            motion_by_obj[oid].sort(key=lambda r: r["frame"])

    state = {}
    for oid, entry in obj_entries.items():
        t_enter = entry["time"]
        if t_enter > start:
            continue

        if oid in motion_by_obj and motion_by_obj[oid]:
            best = None
            for rec in motion_by_obj[oid]:
                if rec["frame"] <= start:
                    if best is None or rec["frame"] > best["frame"]:
                        best = rec
            if best is not None:
                dt = start - best["frame"]
                state[oid] = {
                    "x": best["x"] + best["vx"] * dt,
                    "y": best["y"] + best["vy"] * dt,
                    "vx": best["vx"],
                    "vy": best["vy"],
                    "active": True,
                    "exited": False
                }
            else:
                dt = start - t_enter
                state[oid] = {
                    "x": entry["x"] + entry["vx"] * dt,
                    "y": entry["y"] + entry["vy"] * dt,
                    "vx": entry["vx"],
                    "vy": entry["vy"],
                    "active": True,
                    "exited": False
                }
        else:
            dt = start - t_enter
            state[oid] = {
                "x": entry["x"] + entry["vx"] * dt,
                "y": entry["y"] + entry["vy"] * dt,
                "vx": entry["vx"],
                "vy": entry["vy"],
                "active": True,
                "exited": False
            }

    outcomes = []
    oids_sorted = sorted(state.keys(), key=lambda x: int(x))
    first_iter = True
    collided_pairs = set()

    frame = int(math.ceil(start))
    while frame <= int(horizon):
        if first_iter:
            dt = frame - start
            for o in state.values():
                if o["active"] and not o["exited"]:
                    o["x"] += o["vx"] * dt
                    o["y"] += o["vy"] * dt
            first_iter = False
        else:
            for o in state.values():
                if o["active"] and not o["exited"]:
                    o["x"] += o["vx"]
                    o["y"] += o["vy"]

        for oid in oids_sorted:
            o = state[oid]
            if o["active"] and not o["exited"]:
                if abs(o["x"]) > exit_bound or abs(o["y"]) > exit_bound:
                    outcomes.append({
                        "kind": "exit",
                        "time": float(frame),
                        "entities": [oid],
                        "value": None
                    })
                    o["exited"] = True

        for i in range(len(oids_sorted)):
            for j in range(i + 1, len(oids_sorted)):
                oi, oj = oids_sorted[i], oids_sorted[j]
                if not state[oi]["active"] or state[oi]["exited"] or not state[oj]["active"] or state[oj]["exited"]:
                    continue
                pair = (min(oi, oj), max(oi, oj))
                if pair in collided_pairs:
                    continue
                o1, o2 = state[oi], state[oj]
                dx = o2["x"] - o1["x"]
                dy = o2["y"] - o1["y"]
                dist = math.hypot(dx, dy)
                if dist < collision_threshold and dist > 1e-6:
                    nx = dx / dist
                    ny = dy / dist
                    dvx = o1["vx"] - o2["vx"]
                    dvy = o1["vy"] - o2["vy"]
                    dvn = dvx * nx + dvy * ny
                    if dvn > 0:
                        outcomes.append({
                            "kind": "collision",
                            "time": float(frame),
                            "entities": [oi, oj],
                            "value": None
                        })
                        o1["vx"] -= dvn * nx
                        o1["vy"] -= dvn * ny
                        o2["vx"] += dvn * nx
                        o2["vy"] += dvn * ny
                        shift = (collision_threshold - dist) / 2.0 + 1e-4
                        o1["x"] -= shift * nx
                        o1["y"] -= shift * ny
                        o2["x"] += shift * nx
                        o2["y"] += shift * ny
                        collided_pairs.add(pair)

        frame += 1

    return outcomes
